    /** Paket soneki için izinli id kümesi; bilinmeyen pakette null (fabrika patlar). */
    fun allowed(suffix: String): Set<String>? = when (suffix) {
        "tr" -> trIds
        "tr18" -> tr18Ids
        "global" -> globalIds
        "global18" -> global18Ids
        "test" -> testIds
        "test18" -> test18Ids
        else -> null
    }

